profile /bin/kill flags=(attach_disconnected) {
    # Deny kill for everyone
    deny /bin/kill rix,

    # Allow "sudo" group users
    profile /bin/kill flags=(attach_disconnected) {
        # Allow sudo group users
        allow /bin/kill rix,
        # You can specify the sudo group if needed by adding: group sudo rix,
    }
}

